file.content:
  {/* Recurring weekly */}
  <button
    type="button"
    onClick={() => setRecurringEnabled(v => !v)}
    className={`w-full flex items-center gap-2 px-2.5 py-2 rounded-lg border transition-colors ${recurringEnabled ? "bg-primary/5 border-primary/30" : "bg-muted/20 border-transparent hover:bg-muted/40"}`}
  >
    <RotateCcw className={`w-3.5 h-3.5 shrink-0 ${recurringEnabled ? "text-primary" : "text-muted-foreground"}`} />
    <span className="text-xs font-medium flex-1 text-left truncate">Kartoti kas savaitę</span>
    <span onClick={e => e.stopPropagation()}>
      <Switch checked={recurringEnabled} onCheckedChange={setRecurringEnabled} />
    </span>
  </button>

  {/* Recurring expansion — weeks selector + conflict preview */}
  {recurringEnabled && (
    <div className="p-3 bg-slate-50 dark:bg-muted/20 rounded-md border border-slate-100 dark:border-border space-y-2.5">
      <div className="flex items-center gap-3 text-sm">
        <RotateCcw className="w-3.5 h-3.5 text-primary shrink-0" />
        <span className="text-muted-foreground">Savaitės:</span>
        <select
          value={recurringWeeks}
          onChange={e => setRecurringWeeks(Number(e.target.value))}
          className="ml-auto font-semibold bg-background border rounded-lg px-2 py-1 text-sm focus:outline-none focus:ring-1 focus:ring-primary"
        >
          {[2, 3, 4, 6, 8, 12].map(n => (
            <option key={n} value={n}>{n} sav.</option>
          ))}
        </select>
      </div>
      {/* Conflict preview — one row per week */}
      <div className="space-y-1 pt-0.5">
        {Array.from({ length: recurringWeeks }, (_, i) => {
          const d = new Date(date);
          d.setDate(d.getDate() + i * 7);
          const label = d.toLocaleDateString("lt-LT", { month: "short", day: "numeric", weekday: "short" });
          const status = weekStatuses[i];
          return (
            <div key={i} className="flex items-center gap-2 text-xs">
              {status === null ? (
                <span className="w-3 h-3 rounded-full border border-muted-foreground/30 animate-pulse bg-muted-foreground/10 shrink-0" />
              ) : status ? (
                <CheckCircle2 className="w-3 h-3 text-green-500 shrink-0" />
              ) : (
                <AlertCircle className="w-3 h-3 text-destructive shrink-0" />
              )}
              <span className={`flex-1 capitalize ${status === false ? "line-through text-muted-foreground/50" : "text-foreground/80"}`}>{label}</span>
              {status === false && <span className="text-destructive/70 text-[10px]">užimta</span>}
            </div>
          );
        })}
      </div>
      {/* Available count summary */}
      {weekStatuses.length === recurringWeeks && weekStatuses.some(s => s !== null) && (
        <p className="text-xs text-muted-foreground pt-0.5 border-t border-slate-100 dark:border-border">
          {weekStatuses.filter(s => s === true).length} iš {recurringWeeks} savaitių laisvos
          {selectedSlotRange.totalPrice > 0 && weekStatuses.filter(s => s === true).length > 0 && (
            <span className="font-semibold text-foreground ml-1">
              · {(selectedSlotRange.totalPrice * weekStatuses.filter(s => s === true).length).toFixed(2)} €
            </span>
          )}
        </p>
      )}
    </div>
  )}

  {/* Split payment — conditional */}
  {isSignedIn && selectedSlotRange.totalPrice > 0 && (
    <button
      type="button"
      onClick={() => !isLastMinute && setSplitEnabled(o => !o)}
      disabled={isLastMinute}
      className={`w-full flex items-center gap-2 px-2.5 py-2 rounded-lg border transition-colors ${isLastMinute ? "opacity-40 cursor-not-allowed bg-muted/10 border-transparent" : splitEnabled ? "bg-primary/5 border-primary/30" : "bg-muted/20 border-transparent hover:bg-muted/40"}`}
    >
      <Users className={`w-3.5 h-3.5 shrink-0 ${splitEnabled && !isLastMinute ? "text-primary" : "text-muted-foreground"}`} />
      <span className="text-xs font-medium flex-1 text-left truncate">Skaidyti mokėjimą</span>
      <span onClick={e => e.stopPropagation()}>
        <Switch checked={splitEnabled && !isLastMinute} onCheckedChange={v => !isLastMinute && setSplitEnabled(v)} disabled={isLastMinute} />
      </span>
    </button>
  )}
</div>

{/* Last-minute split notice */}
{isSignedIn && selectedSlotRange.totalPrice > 0 && isLastMinute && (
  <p className="px-1 text-xs text-muted-foreground">Paskutinės minutės rezervacijas būtina apmokėti pilnai.</p>

