        <Users className={`w-3.5 h-3.5 shrink-0 ${splitEnabled && !isLastMinute && !recurringEnabled ? "text-primary" : "text-muted-foreground"}`} />
        <span className="text-xs font-medium flex-1 text-left truncate">Skaidyti mokėjimą</span>
        <span onClick={e => e.stopPropagation()}>
          <Switch
            checked={splitEnabled && !isLastMinute && !recurringEnabled}
            onCheckedChange={v => { if (!isLastMinute) { setSplitEnabled(v); if (v) setRecurringEnabled(false); } }}
            disabled={isLastMinute || recurringEnabled}
          />
        </span>
      </button>
    </TooltipTrigger>
    {recurringEnabled && (
      <TooltipContent side="top" className="text-xs max-w-[220px] text-center">
        Mokėjimo skaidymas negalimas kartotinėms rezervacijoms
      </TooltipContent>
    )}
  </Tooltip>
)}

