import pathlib, re

data = pathlib.Path('/home/runner/workspace/.config/npm/node_global/lib/node_modules/@anthropic-ai/claude-code/bin/claude.exe').read_bytes().decode('latin-1')

# Find where plugins.errors is SET in the store (not just read)
# Look for dispatch calls or state updates with errors
for pattern in ['plugins:{', 'plugins.errors:', "plugins,{errors", "errors:K", "errors:_"]:
    idx = data.find(pattern)
    if idx >= 0:
        ctx = data[max(0,idx-300):idx+500]
        clean = re.sub(r'[^\x20-\x7e]', '.', ctx)
        if 'plugin' in clean.lower():
            print(f"=== '{pattern}' at {idx} ===")
            for chunk in re.split(r'\.{4,}', clean):
                s = chunk.strip()
                if len(s) > 8:
                    print(' ', s[:200])
            print()

# Also look for setPlugins or dispatchPlugins
for pattern in ['setPlugins', 'dispatchPlugin', 'pluginsState', 'plugins:pY']:
    idx = data.find(pattern)
    if idx >= 0:
        ctx = data[max(0,idx-100):idx+300]
        clean = re.sub(r'[^\x20-\x7e]', '.', ctx)
        print(f"=== '{pattern}' at {idx} ===")
        for chunk in re.split(r'\.{3,}', clean):
            s = chunk.strip()
            if len(s) > 5:
                print(' ', s[:200])
        print()
EOF

python3 << 'EOF'
import pathlib, re

data = pathlib.Path('/home/runner/workspace/.config/npm/node_global/lib/node_modules/@anthropic-ai/claude-code/bin/claude.exe').read_bytes().decode('latin-1')

# Find the initial plugins state - it's defined in the store setup
