idx = data.find('plugins:{')
while idx >= 0:
    ctx = data[max(0,idx-100):idx+500]
    clean = re.sub(r'[^\x20-\x7e]', '.', ctx)
    if 'errors' in clean and 'warnings' in clean:
        print(f"=== at {idx} ===")
        for chunk in re.split(r'\.{4,}', clean):
            s = chunk.strip()
            if len(s) > 8:
                print(' ', s[:200])
        print()
    idx = data.find('plugins:{', idx+1)
    if idx > 232000000:
        break
EOF

