1	import { useState, useEffect, type FormEvent } from "react";
2	import { useLocation } from "wouter";
3	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
4	import { CoachLayout } from "@/components/coach-layout";
5	import { Button } from "@/components/ui/button";
6	import { Label } from "@/components/ui/label";
7	import { Switch } from "@/components/ui/switch";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
10	import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
11	import { useToast } from "@/hooks/use-toast";
12	import { customFetch } from "@workspace/api-client-react";
13	import { centsToEuroString } from "@/lib/money";
14	import { useViewAsCoach, withCoachViewAs } from "@/lib/view-as-coach";
15	import { CoachAffiliations } from "@/components/coach-affiliations";
16	import { PromoteButton } from "@/components/promote-button";
17	import { CoachProfileForm } from "@/components/coach-profile-form";
18	import { CoachWeeklyHours } from "@/components/coach-weekly-hours";
19	import { CoachBlockedSlots } from "@/components/coach-blocked-slots";
20	import { AlertTriangle, ExternalLink } from "lucide-react";
21	
22	const VALID_TABS = ["profile", "general", "hours", "blocks"] as const;
23	type SettingsTab = (typeof VALID_TABS)[number];
24	
25	function readTabFromUrl(): SettingsTab {
26	  if (typeof window === "undefined") return "profile";
27	  const raw = new URLSearchParams(window.location.search).get("tab");
28	  return (VALID_TABS as readonly string[]).includes(raw ?? "")
29	    ? (raw as SettingsTab)
30	    : "profile";
31	}
32	
33	const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
34	const API = `${BASE}/api`;
35	
36	type TravelPolicy = "any_court" | "affiliated_only";
37	type CourtPaymentModel = "student_pays_court" | "coach_pays_court";
38	type CoachCancellationPolicy = "flexible" | "standard" | "strict";
39	
40	interface MyCoachProfile {
41	  id: number;
42	  userId: string;
43	  name: string;
44	  email: string;
45	  bio?: string | null;
46	  phone?: string | null;
47	  pricePerHour?: number | null;
48	  isAcceptingStudents?: boolean;
49	  experienceYears?: number | null;
50	  qualifications?: string[];
51	  sports?: string[];
52	  // Legacy free-text working-hours blurb, no longer edited but still rendered
53	  // on public pages — passed through in the save body so it isn't wiped.
54	  availabilityDescription?: string | null;
55	  travelPolicy?: TravelPolicy;
56	  courtPaymentModel?: CourtPaymentModel;
57	  cancellationPolicy?: CoachCancellationPolicy;
58	  promotedUntil?: string | null;
59	}
60	
61	interface FormState {
62	  isAcceptingStudents: boolean;
63	  travelPolicy: TravelPolicy;
64	  courtPaymentModel: CourtPaymentModel;
65	  cancellationPolicy: CoachCancellationPolicy;
66	}
67	
68	const EMPTY_FORM: FormState = {
69	  isAcceptingStudents: true,
70	  travelPolicy: "affiliated_only",
71	  courtPaymentModel: "student_pays_court",
72	  cancellationPolicy: "standard",
73	};
74	
75	export default function CoachSettings() {
76	  const { toast } = useToast();
77	  const qc = useQueryClient();
78	
79	  const { asCoachId } = useViewAsCoach();
80	  const isViewingAs = asCoachId != null;
81	  const { data: profile, isLoading } = useQuery<MyCoachProfile>({
82	    queryKey: ["coach-me-profile", asCoachId],
83	    queryFn: () => customFetch<MyCoachProfile>(withCoachViewAs(`${API}/coaches/me`)),
84	    staleTime: 60_000,
85	  });
86	
87	  type StripeStatusValue = "not_connected" | "pending" | "active";
88	  const { data: stripeStatus } = useQuery<{
89	    status: StripeStatusValue;
90	    accountId: string | null;
91	    disabledReason?: string | null;
92	  }>({
93	    queryKey: ["stripe-connect-status"],
94	    queryFn: () => customFetch(`${API}/stripe/connect/status`),
95	  });
96	  const isHiddenFromMarketplace =
97	    stripeStatus != null && stripeStatus.status !== "active";
98	
99	  useEffect(() => {
100	    const onFocus = () => {
101	      qc.invalidateQueries({ queryKey: ["stripe-connect-status"] });
102	    };
103	    window.addEventListener("focus", onFocus);
104	    return () => window.removeEventListener("focus", onFocus);
105	  }, [qc]);
106	
107	  const [stripeOpening, setStripeOpening] = useState(false);
108	  const openStripeConnect = async () => {
109	    setStripeOpening(true);
110	    try {
111	      const r = await customFetch<{ url: string }>(`${API}/stripe/connect`, {
112	        method: "POST",
113	      });
114	      window.open(r.url, "_blank", "noopener,noreferrer");
115	    } catch (err) {
116	      toast({
117	        title: "Klaida atidarant Stripe",
118	        description: (err as Error).message,
119	        variant: "destructive",
120	      });
121	    } finally {
122	      setStripeOpening(false);
123	    }
124	  };
125	
126	  const [form, setForm] = useState<FormState>(EMPTY_FORM);
127	
128	  // Seed the form from the server response once it arrives.
129	  useEffect(() => {
130	    if (!profile) return;
131	    setForm({
132	      isAcceptingStudents: profile.isAcceptingStudents ?? true,
133	      travelPolicy: profile.travelPolicy ?? "affiliated_only",
134	      courtPaymentModel: profile.courtPaymentModel ?? "student_pays_court",
135	      cancellationPolicy: profile.cancellationPolicy ?? "standard",
136	    });
137	  }, [profile]);
138	
139	  const save = useMutation({
140	    mutationFn: async () => {
141	      // /coaches/me PUT expects the full upsert body — name/email/bio/sports/
142	      // photo/etc are owned by /coach/profile, so we resend them unchanged
143	      // from the server-known profile to avoid wiping them.
144	      if (!profile) throw new Error("Profilis dar nepasiruošė");
145	      return customFetch<MyCoachProfile>(`${API}/coaches/me`, {
146	        method: "PUT",
147	        headers: { "Content-Type": "application/json" },
148	        body: JSON.stringify({
149	          name: profile.name,
150	          email: profile.email,
151	          bio: profile.bio ?? null,
152	          phone: profile.phone ?? null,
153	          sports: profile.sports ?? [],
154	          availabilityDescription: profile.availabilityDescription ?? null,
155	          experienceYears: profile.experienceYears ?? null,
156	          qualifications: profile.qualifications ?? [],
157	          isAcceptingStudents: form.isAcceptingStudents,
158	          travelPolicy: form.travelPolicy,
159	          courtPaymentModel: form.courtPaymentModel,
160	          cancellationPolicy: form.cancellationPolicy,
161	        }),
162	      });
163	    },
164	    onSuccess: () => {
165	      toast({ title: "Nustatymai išsaugoti" });
166	      qc.invalidateQueries({ queryKey: ["coach-me-profile"] });
167	      qc.invalidateQueries({ queryKey: ["coach"] });
168	      qc.invalidateQueries({ queryKey: ["coaches"] });
169	    },
170	    onError: (e: Error) => {
171	      toast({ title: "Klaida", description: e.message, variant: "destructive" });
172	    },
173	  });
174	
175	  function onSubmit(e: FormEvent<HTMLFormElement>) {
176	    e.preventDefault();
177	    if (save.isPending) return;
178	    save.mutate();
179	  }
180	
181	  // URL-driven tab state. `?tab=profile|general|hours|blocks` survives reloads
182	  // and lets other parts of the app deep-link to a specific section. We
183	  // initialize from the URL once and use replaceState on changes so back/forward
184	  // history isn't littered with every tab click.
185	  const [, navigate] = useLocation();
186	  const [tab, setTab] = useState<SettingsTab>(readTabFromUrl);
187	  useEffect(() => {
188	    const params = new URLSearchParams(window.location.search);
189	    const current = params.get("tab");
190	    if (current === tab) return;
191	    if (tab === "profile" && (current == null || current === "")) return;
192	    params.set("tab", tab);
193	    navigate(`/coach/settings?${params.toString()}`, { replace: true });
194	  }, [tab, navigate]);
195	
196	  return (
197	    <CoachLayout title="Nustatymai">
198	      <div className="px-4 md:px-6 py-6 max-w-3xl space-y-6">
199	        <header className="flex flex-col gap-1">
200	          <h1 className="text-2xl font-semibold tracking-tight">Nustatymai</h1>
201	          <p className="text-sm text-muted-foreground">
202	            Veiklos politika, mokėjimai ir darbo valandos.
203	          </p>
204	        </header>
205	
206	        {isHiddenFromMarketplace && (
207	          <div
208	            role="alert"
209	            className="rounded-2xl border-2 border-destructive/40 bg-destructive/10 p-4 flex items-start gap-3"
210	          >
211	            <AlertTriangle className="w-5 h-5 text-destructive shrink-0 mt-0.5" />
212	            <div className="flex-1 min-w-0 space-y-2">
213	              <p className="text-sm font-semibold text-destructive">
214	                ⚠️ Jūsų profilis yra paslėptas nuo žaidėjų
215	              </p>
216	              <p className="text-sm text-destructive/90">
217	                Prijunkite arba atnaujinkite banko sąskaitos informaciją, kad galėtumėte priimti užsakymus.
218	                Paslaugų katalogą galite ruošti ir dabar — jis taps matomas iškart, kai Stripe sąskaita bus aktyvuota.
219	              </p>
220	              {stripeStatus?.disabledReason && (
221	                <p className="text-xs text-destructive/80">
222	                  Stripe priežastis: <code className="font-mono">{stripeStatus.disabledReason}</code>
223	                </p>
224	              )}
225	              <Button
226	                size="sm"
227	                variant="destructive"
228	                onClick={openStripeConnect}
229	                disabled={stripeOpening}
230	              >
231	                {stripeStatus?.status === "pending"
232	                  ? "Užbaigti Stripe sąskaitos patvirtinimą"
233	                  : "Prijungti banko sąskaitą"}
234	                <ExternalLink className="w-3.5 h-3.5 ml-1.5" />
235	              </Button>
236	            </div>
237	          </div>
