154	  const { getToken } = useAuth();
155	
156	  const [, setLocation] = useLocation();
157	  const { toast } = useToast();
158	  const { isAdmin } = useRole();
159	  const qc = useQueryClient();
160	
161	  const isOwnProfileRoute = !id || id === "me";
162	  const { asCoachId, asCoachName, enter: enterViewAs, exit: exitViewAs } = useViewAsCoach();
163	
164	  const { data: coach, isLoading } = useQuery<Coach | null>({
165	    queryKey: isOwnProfileRoute ? ["coach", "me", asCoachId] : ["coach", id],
166	    queryFn: isOwnProfileRoute ? () => fetchMyCoach(asCoachId) : () => fetchCoach(id!),
