168	    retry: false,
169	  });
170	
171	  const isOwn = isOwnProfileRoute || (coach?.userId && user?.id === coach.userId);
172	  const coachId = coach?.id;
173	
174	  // Public facilities the coach is approved at — visible on every profile view
175	  const facilitiesQ = useQuery<CoachFacilityGroup[]>({
176	    queryKey: ["coach-facilities", coachId],
177	    queryFn: () => fetch(`${API}/coaches/${coachId}/facilities`).then(r => r.json()),
