183	  const servicesQ = useQuery<CoachService[]>({
184	    queryKey: ["coach-services", coachId],
185	    queryFn: () => fetch(`${API}/coaches/${coachId}/services`, { credentials: "include" }).then(r => r.ok ? r.json() : []),
186	    enabled: !!coachId,
187	  });
188	
189	  // Public review feed, paginated. "Rodyti daugiau" appends the next page via
190	  // useInfiniteQuery; each page request returns hasMore so the button hides
