220	  const galleryQ = useQuery<GalleryPhoto[]>({
221	    queryKey: ["coach-gallery", coachId],
222	    queryFn: () => fetch(`${API}/coaches/${coachId}/gallery`).then(r => r.json()),
223	    enabled: !!coachId,
224	  });
225	  const [lightboxIdx, setLightboxIdx] = useState<number | null>(null);
