231	    setUploading(true);
232	    try {
233	      const token = await getToken();
234	      const fd = new FormData();
235	      fd.append("image", file);
236	      const res = await fetch(`${API}/coaches/${coachId}/photos`, {
237	        method: "POST",
238	        headers: token ? { Authorization: `Bearer ${token}` } : {},
239	        body: fd,
