487	      {isOwn && !asCoachName && (
488	        <div
489	          role="status"
490	          className="sticky top-16 z-30 flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-3 px-4 py-3 bg-primary/10 border-b border-primary/30 text-foreground"
491	        >
492	          <span className="text-sm flex-1 min-w-0">
