506	      <div className="container mx-auto px-4 py-12 max-w-2xl space-y-6">
507	
508	        {/* Back link */}
509	        <BackButton to="/coaches" label="Visi treneriai" />
510	
511	        {/* Header card */}
512	        <div className="bg-card border rounded-2xl p-6 shadow-sm">
513	          <div className="flex items-start justify-between gap-4">
514	            <div className="flex items-center gap-4">
515	              {displayCoach?.photoUrl ? (
516	                <img
