525	              )}
526	              <div>
527	                <h1 className="text-2xl font-bold">{displayCoach?.name ?? (isOwnProfileRoute ? "Trenerio profilis" : "")}</h1>
528	                {displayCoach?.email && (
529	                  <p className="text-sm text-muted-foreground flex items-center gap-1.5 mt-0.5">
530	                    <Mail className="w-3.5 h-3.5" />
531	                    {displayCoach.email}
532	                  </p>
