import { useState, useEffect, type ReactNode, type ComponentType } from "react";
import { useLocation } from "wouter";
import {
  LayoutDashboard,
  Users,
  MessageSquare,
  Settings,
  Menu,
  X,
  ChevronDown,
  Star,
  Sparkles,
  ExternalLink,
  Receipt,
} from "lucide-react";
import { Layout } from "@/components/layout";
import { useRole } from "@/lib/useRole";
import { useViewAsCoach } from "@/lib/view-as-coach";
import { Eye } from "lucide-react";

const BASE_URL = import.meta.env.BASE_URL.replace(/\/$/, "");

interface NavItem {
  icon: ComponentType<{ className?: string }>;
  label: string;
  href: string;
  match: (location: string) => boolean;
}

const NAV_ITEMS: NavItem[] = [
  {
    icon: LayoutDashboard,
    label: "Apžvalga",
    href: "/coach/dashboard",
    match: (l) => l.startsWith("/coach/dashboard"),
  },
  {
    icon: Sparkles,
    label: "Paslaugos",
    href: "/coach/services",
    match: (l) => l.startsWith("/coach/services"),
  },
  {
    icon: Receipt,
    label: "Rezervacijos",
    href: "/coach/bookings",
    match: (l) => l.startsWith("/coach/bookings"),
  },
  {
    icon: Users,
    label: "Mokiniai",
    href: "/coach/students",
    match: (l) => l.startsWith("/coach/students"),
  },
  {
    icon: MessageSquare,
    label: "Žinutės",
    href: "/coach/messages",
    match: (l) => l.startsWith("/coach/messages"),
  },
  {
    icon: Star,
    label: "Atsiliepimai",
    href: "/coach/reviews",
    match: (l) => l.startsWith("/coach/reviews"),
  },
  {
    icon: Settings,
    label: "Nustatymai",
    href: "/coach/settings",
    // Old /coach/profile and /coach/schedule routes redirect into Settings;
    // highlight Nustatymai while the redirect resolves so the active state
    // doesn't flicker to "no item".
    match: (l) =>
      l.startsWith("/coach/settings")
      || l.startsWith("/coach/profile")
      || l.startsWith("/coach/schedule"),
  },
];

