712	                      <Switch checked={field.value} onCheckedChange={field.onChange} />
713	                    </FormControl>
714	                  </FormItem>
715	                )}
716	              />
717	
718	              <DialogFooter className="gap-2">
719	                <Button
720	                  type="button"
721	                  variant="outline"
722	                  onClick={() => {
