1	/**
2	 * Coach services — bookable lesson types per coach.
3	 *
4	 * A coach has ONE shared availability schedule but MANY services (individual
5	 * lessons, group sessions, junior intro, etc.) each with its own duration and
6	 * price. The marketplace card surfaces the lowest priceCents as a "starting
7	 * from" rate (Invariant A — see lib/coach-pricing.ts).
8	 *
9	 * Endpoints:
10	 *   GET    /coaches/:id/services                — public; lists active
11	 *                                                  services. The owner sees
12	 *                                                  ALL services (incl. inactive).
13	 *   POST   /coaches/:id/services                — owner only
14	 *   PATCH  /coaches/:id/services/:sid           — owner only
15	 *   DELETE /coaches/:id/services/:sid           — owner only; soft-deletes
16	 *                                                  when bookings reference it
17	 *   GET    /coaches/:id/services/:sid/slots     — public; returns start times
18	 *                                                  for the given date that fit
19	 *                                                  the service's duration
20	 *
21	 * All mutating routes wrap the change AND syncCoachStartingPrice in a single
22	 * transaction so the denormalized pricePerHour can never drift out of sync
23	 * with the underlying services.
24	 */
25	import { Router, type IRouter } from "express";
26	import { and, asc, eq, ne, sql } from "drizzle-orm";
27	import { z } from "zod";
28	import {
29	  db,
30	  coachesTable,
31	  coachServicesTable,
32	  courtCoachesTable,
33	  bookingsTable,
34	} from "@workspace/db";
35	import { requireAuth, getCurrentUserId } from "../lib/auth";
36	import { syncCoachStartingPrice } from "../lib/coach-pricing";
37	import { getCoachAvailability } from "../lib/coach-availability";
38	
39	const router: IRouter = Router();
40	
41	// ─── Helpers ────────────────────────────────────────────────────────────────
42	
43	/**
44	 * Shape returned to API consumers. Explicit projection — never spread the
45	 * raw DB row.
46	 */
47	function formatService(s: typeof coachServicesTable.$inferSelect) {
48	  return {
49	    id: s.id,
50	    coachId: s.coachId,
51	    name: s.name,
52	    description: s.description,
53	    sport: s.sport,
54	    courtId: s.courtId,
55	    durationMin: s.durationMin,
56	    priceCents: s.priceCents,
57	    maxParticipants: s.maxParticipants,
58	    audienceLevel: s.audienceLevel,
59	    isActive: s.isActive,
60	    sortOrder: s.sortOrder,
61	    createdAt: s.createdAt,
62	    updatedAt: s.updatedAt,
63	  };
64	}
65	
66	const ALLOWED_DURATIONS = [30, 60, 90, 120] as const;
67	
68	const serviceCreateSchema = z.object({
69	  name: z.string().trim().min(1).max(120),
70	  description: z.string().trim().max(1000).optional().nullable(),
71	  sport: z.string().trim().min(1).max(64),
72	  courtId: z.number().int().positive().optional().nullable(),
73	  durationMin: z.number().int().refine(v => (ALLOWED_DURATIONS as readonly number[]).includes(v), {
74	    message: "durationMin must be 30, 60, 90, or 120",
75	  }),
76	  priceCents: z.number().int().nonnegative(),
77	  maxParticipants: z.number().int().min(1).max(8).optional(),
78	  audienceLevel: z.string().trim().max(32).optional().nullable(),
79	  isActive: z.boolean().optional(),
80	  sortOrder: z.number().int().optional(),
81	});
82	
83	// All fields optional for PATCH; same value rules as create.
84	const serviceUpdateSchema = serviceCreateSchema.partial();
85	
86	type LoadedCoach =
87	  | { kind: "ok"; coach: { id: number; userId: string } }
88	  | { kind: "err"; status: number; body: { error: string } };
89	
90	async function loadOwnedCoach(
91	  req: import("express").Request,
92	  coachId: number,
93	): Promise<LoadedCoach> {
94	  const userId = getCurrentUserId(req);
95	  if (!userId) return { kind: "err", status: 401, body: { error: "Unauthorized" } };
96	  const [coach] = await db
97	    .select({ id: coachesTable.id, userId: coachesTable.userId })
98	    .from(coachesTable)
99	    .where(eq(coachesTable.id, coachId));
100	  if (!coach) return { kind: "err", status: 404, body: { error: "Coach not found" } };
101	  if (coach.userId !== userId) {
102	    return { kind: "err", status: 403, body: { error: "Forbidden" } };
103	  }
104	  return { kind: "ok", coach };
105	}
106	
107	/**
108	 * Confirm a service's courtId (when supplied) is one the coach is approved
109	 * at. Without this check a coach could bind a service to any court id in
110	 * the database, including courts of competitors.
111	 */
112	async function assertCoachOwnsCourt(coachId: number, courtId: number): Promise<boolean> {
113	  const [row] = await db
114	    .select({ id: courtCoachesTable.id })
115	    .from(courtCoachesTable)
116	    .where(and(eq(courtCoachesTable.coachId, coachId), eq(courtCoachesTable.courtId, courtId)));
117	  return !!row;
118	}
119	
120	// ─── GET /coaches/:id/services ─────────────────────────────────────────────
121	
122	router.get("/coaches/:id/services", async (req, res): Promise<void> => {
123	  const coachId = parseInt(String(req.params.id), 10);
124	  if (!Number.isFinite(coachId)) {
125	    res.status(400).json({ error: "Invalid coach id" });
126	    return;
127	  }
128	
129	  const [coach] = await db
130	    .select({ id: coachesTable.id, userId: coachesTable.userId, status: coachesTable.status })
131	    .from(coachesTable)
132	    .where(eq(coachesTable.id, coachId));
133	  if (!coach) {
134	    res.status(404).json({ error: "Coach not found" });
135	    return;
136	  }
137	
138	  const callerId = getCurrentUserId(req);
139	  const isOwnerCaller = callerId !== null && callerId === coach.userId;
140	
141	  // Non-owners can only see services for an approved coach AND only active
142	  // services. The owner sees all services regardless of approval status —
143	  // they need to be able to manage their menu before going live.
144	  if (!isOwnerCaller && coach.status !== "approved") {
145	    res.status(404).json({ error: "Coach not found" });
146	    return;
147	  }
148	
149	  const conditions = [eq(coachServicesTable.coachId, coachId)];
150	  if (!isOwnerCaller) conditions.push(eq(coachServicesTable.isActive, true));
151	
152	  const rows = await db
153	    .select()
154	    .from(coachServicesTable)
155	    .where(and(...conditions))
156	    .orderBy(asc(coachServicesTable.sortOrder), asc(coachServicesTable.id));
157	
158	  res.json(rows.map(formatService));
159	});
160	
161	// ─── POST /coaches/:id/services ────────────────────────────────────────────
162	
163	router.post("/coaches/:id/services", requireAuth, async (req, res): Promise<void> => {
164	  const coachId = parseInt(String(req.params.id), 10);
165	  if (!Number.isFinite(coachId)) {
166	    res.status(400).json({ error: "Invalid coach id" });
167	    return;
168	  }
169	  const owned = await loadOwnedCoach(req, coachId);
170	  if (owned.kind === "err") {
171	    res.status(owned.status).json(owned.body);
172	    return;
173	  }
174	
175	  const parsed = serviceCreateSchema.safeParse(req.body);
176	  if (!parsed.success) {
177	    res.status(400).json({ error: "Invalid payload", details: parsed.error.flatten() });
178	    return;
179	  }
180	  const v = parsed.data;
181	
182	  if (v.courtId != null) {
183	    const ok = await assertCoachOwnsCourt(coachId, v.courtId);
184	    if (!ok) {
185	      res.status(400).json({ error: "Coach is not approved at the supplied courtId" });
186	      return;
187	    }
188	  }
189	
190	  // Catalog ceiling: 15 services per coach. Counts BOTH active and inactive
191	  // rows — a soft-deactivated service still occupies a catalog slot until
192	  // it's removed via DELETE.
193	  const SERVICE_CATALOG_LIMIT = 15;
194	  const [{ count }] = await db
195	    .select({ count: sql<number>`COUNT(*)::int` })
196	    .from(coachServicesTable)
197	    .where(eq(coachServicesTable.coachId, coachId));
198	  if (count >= SERVICE_CATALOG_LIMIT) {
199	    res.status(422).json({
200	      error: "service_catalog_full",
201	      message: `Maksimalus paslaugų skaičius (${SERVICE_CATALOG_LIMIT}) pasiektas`,
202	    });
203	    return;
204	  }
205	
206	  try {
207	    const created = await db.transaction(async (tx) => {
208	      const [row] = await tx
209	        .insert(coachServicesTable)
210	        .values({
211	          coachId,
212	          name: v.name,
213	          description: v.description ?? null,
214	          sport: v.sport,
215	          courtId: v.courtId ?? null,
216	          durationMin: v.durationMin,
217	          priceCents: v.priceCents,
218	          maxParticipants: v.maxParticipants ?? 1,
219	          audienceLevel: v.audienceLevel ?? null,
220	          isActive: v.isActive ?? true,
221	          sortOrder: v.sortOrder ?? 0,
222	          updatedAt: new Date(),
223	        })
224	        .returning();
225	      await syncCoachStartingPrice(coachId, tx);
226	      return row;
227	    });
228	    res.status(201).json(formatService(created));
229	  } catch (err) {
230	    console.error("[coach-services] POST failed", err);
231	    res.status(500).json({ error: "Failed to create service" });
232	  }
233	});
234	
235	// ─── PATCH /coaches/:id/services/:sid ──────────────────────────────────────
236	
237	router.patch("/coaches/:id/services/:sid", requireAuth, async (req, res): Promise<void> => {
238	  const coachId = parseInt(String(req.params.id), 10);
239	  const serviceId = parseInt(String(req.params.sid), 10);
240	  if (!Number.isFinite(coachId) || !Number.isFinite(serviceId)) {
241	    res.status(400).json({ error: "Invalid id" });
242	    return;
243	  }
244	
245	  const owned = await loadOwnedCoach(req, coachId);
246	  if (owned.kind === "err") {
247	    res.status(owned.status).json(owned.body);
248	    return;
249	  }
250	
251	  const parsed = serviceUpdateSchema.safeParse(req.body);
252	  if (!parsed.success) {
253	    res.status(400).json({ error: "Invalid payload", details: parsed.error.flatten() });
254	    return;
255	  }
256	  const v = parsed.data;
257	
258	  // Confirm the service belongs to this coach (object-level authz).
259	  const [existing] = await db
260	    .select({ id: coachServicesTable.id, coachId: coachServicesTable.coachId })
261	    .from(coachServicesTable)
262	    .where(eq(coachServicesTable.id, serviceId));
263	  if (!existing || existing.coachId !== coachId) {
264	    res.status(404).json({ error: "Service not found" });
265	    return;
266	  }
267	
268	  if (v.courtId != null) {
269	    const ok = await assertCoachOwnsCourt(coachId, v.courtId);
270	    if (!ok) {
271	      res.status(400).json({ error: "Coach is not approved at the supplied courtId" });
272	      return;
273	    }
274	  }
275	
276	  // Build only the columns the caller actually supplied. This keeps the
277	  // PATCH partial (Invariant B-friendly — we never silently rewrite columns
278	  // the client didn't touch).
279	  const patch: Partial<typeof coachServicesTable.$inferInsert> = { updatedAt: new Date() };
280	  if (v.name !== undefined) patch.name = v.name;
281	  if (v.description !== undefined) patch.description = v.description ?? null;
282	  if (v.sport !== undefined) patch.sport = v.sport;
283	  if (v.courtId !== undefined) patch.courtId = v.courtId ?? null;
284	  if (v.durationMin !== undefined) patch.durationMin = v.durationMin;
285	  if (v.priceCents !== undefined) patch.priceCents = v.priceCents;
286	  if (v.maxParticipants !== undefined) patch.maxParticipants = v.maxParticipants;
287	  if (v.audienceLevel !== undefined) patch.audienceLevel = v.audienceLevel ?? null;
288	  if (v.isActive !== undefined) patch.isActive = v.isActive;
289	  if (v.sortOrder !== undefined) patch.sortOrder = v.sortOrder;
290	
291	  try {
292	    const updated = await db.transaction(async (tx) => {
293	      const [row] = await tx
294	        .update(coachServicesTable)
295	        .set(patch)
296	        .where(eq(coachServicesTable.id, serviceId))
297	        .returning();
298	      await syncCoachStartingPrice(coachId, tx);
299	      return row;
300	    });
301	    if (!updated) {
302	      res.status(404).json({ error: "Service not found" });
303	      return;
304	    }
305	    res.json(formatService(updated));
306	  } catch (err) {
307	    console.error("[coach-services] PATCH failed", err);
308	    res.status(500).json({ error: "Failed to update service" });
309	  }
310	});
311	
312	// ─── DELETE /coaches/:id/services/:sid ─────────────────────────────────────
313	
314	router.delete("/coaches/:id/services/:sid", requireAuth, async (req, res): Promise<void> => {
315	  const coachId = parseInt(String(req.params.id), 10);
316	  const serviceId = parseInt(String(req.params.sid), 10);
317	  if (!Number.isFinite(coachId) || !Number.isFinite(serviceId)) {
318	    res.status(400).json({ error: "Invalid id" });
319	    return;
320	  }
321	
322	  const owned = await loadOwnedCoach(req, coachId);
323	  if (owned.kind === "err") {
324	    res.status(owned.status).json(owned.body);
325	    return;
326	  }
327	
328	  const [existing] = await db
329	    .select({ id: coachServicesTable.id, coachId: coachServicesTable.coachId })
330	    .from(coachServicesTable)
331	    .where(eq(coachServicesTable.id, serviceId));
332	  if (!existing || existing.coachId !== coachId) {
333	    res.status(404).json({ error: "Service not found" });
334	    return;
335	  }
336	
337	  // Vulnerability check (Invariant B): if any booking still references this
338	  // service we MUST NOT hard-delete — that would lose the historical link
339	  // between the booking and the lesson type the student bought. Soft-delete
340	  // by flipping isActive=false so it disappears from the marketplace and
341	  // booking flows, but the row stays for analytics / refund decisions.
342	  const [refBooking] = await db
343	    .select({ id: bookingsTable.id })
344	    .from(bookingsTable)
345	    .where(eq(bookingsTable.coachServiceId, serviceId))
346	    .limit(1);
347	  const hasBookings = !!refBooking;
348	
349	  try {
350	    const result = await db.transaction(async (tx) => {
351	      if (hasBookings) {
352	        const [row] = await tx
353	          .update(coachServicesTable)
354	          .set({ isActive: false, updatedAt: new Date() })
355	          .where(eq(coachServicesTable.id, serviceId))
356	          .returning();
357	        await syncCoachStartingPrice(coachId, tx);
358	        return { mode: "soft" as const, row };
359	      } else {
360	        await tx
361	          .delete(coachServicesTable)
362	          .where(eq(coachServicesTable.id, serviceId));
363	        await syncCoachStartingPrice(coachId, tx);
364	        return { mode: "hard" as const };
365	      }
366	    });
367	    res.json({ deleted: result.mode === "hard", deactivated: result.mode === "soft" });
368	  } catch (err) {
369	    console.error("[coach-services] DELETE failed", err);
370	    res.status(500).json({ error: "Failed to delete service" });
371	  }
372	});
373	
374	// ─── GET /coaches/:id/services/:sid/slots?date=YYYY-MM-DD ──────────────────
375	
376	const dateRe = /^\d{4}-\d{2}-\d{2}$/;
377	
378	router.get("/coaches/:id/services/:sid/slots", async (req, res): Promise<void> => {
379	  const coachId = parseInt(String(req.params.id), 10);
380	  const serviceId = parseInt(String(req.params.sid), 10);
381	  const date = String(req.query.date ?? "");
382	  if (!Number.isFinite(coachId) || !Number.isFinite(serviceId) || !dateRe.test(date)) {
383	    res.status(400).json({ error: "Invalid request — expect numeric ids and YYYY-MM-DD date" });
384	    return;
385	  }
386	
387	  // Service load — we need duration + courtId. Inactive services don't
388	  // expose slots (so a coach can pull a service from the menu without
389	  // breaking the existing /coach/:id page rendering it).
390	  const [service] = await db
391	    .select({
392	      id: coachServicesTable.id,
393	      coachId: coachServicesTable.coachId,
394	      courtId: coachServicesTable.courtId,
395	      durationMin: coachServicesTable.durationMin,
396	      isActive: coachServicesTable.isActive,
397	    })
398	    .from(coachServicesTable)
399	    .where(eq(coachServicesTable.id, serviceId));
400	  if (!service || service.coachId !== coachId || !service.isActive) {
401	    res.status(404).json({ error: "Service not found" });
402	    return;
403	  }
404	
405	  // Step 1 — coach-side 30-min availability slots for the day.
406	  const coachSlots = await getCoachAvailability(coachId, date);
407	  if (coachSlots.length === 0) {
408	    res.json({ slots: [] });
409	    return;
410	  }
411	
412	  // Step 2 — if the service is court-bound, drop coach slots whose window
413	  // overlaps a court booking on that date. Bookings store HH:MM in Europe/
414	  // Vilnius local time on the supplied date, same convention as the coach
415	  // slot labels — string compare is enough.
416	  let courtBookedRanges: Array<{ startTime: string; endTime: string }> = [];
417	  if (service.courtId != null) {
418	    courtBookedRanges = await db
419	      .select({ startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
420	      .from(bookingsTable)
421	      .where(
422	        and(
423	          eq(bookingsTable.courtId, service.courtId),
424	          eq(bookingsTable.date, date),
425	          ne(bookingsTable.status, "cancelled"),
426	        ),
427	      );
428	  }
429	
430	  function isCourtBlockedAtLabel(hhmm: string): boolean {
431	    // half-open [start, end) overlap — slot starting at hhmm covers the 30
432	    // minutes hhmm..(hhmm+30). Easiest: compare HH:MM strings since they
433	    // sort lexicographically when zero-padded.
434	    const slotStart = hhmm;
435	    const [hh, mm] = hhmm.split(":").map(Number);
436	    const endMins = hh * 60 + mm + 30;
437	    const slotEnd = `${String(Math.floor(endMins / 60)).padStart(2, "0")}:${String(endMins % 60).padStart(2, "0")}`;
438	    for (const r of courtBookedRanges) {
439	      // Overlap if r.startTime < slotEnd AND r.endTime > slotStart
440	      if (r.startTime < slotEnd && r.endTime > slotStart) return true;
441	    }
442	    return false;
443	  }
444	
445	  // Step 3 — collapse to start times where the next N consecutive 30-min
446	  // slots are all available. N = durationMin / 30.
447	  const slotsNeeded = Math.ceil(service.durationMin / 30);
448	  const labelToIdx = new Map<string, number>();
449	  coachSlots.forEach((s, i) => labelToIdx.set(s.label, i));
450	
451	  function nextLabel(hhmm: string): string {
452	    const [hh, mm] = hhmm.split(":").map(Number);
453	    const t = hh * 60 + mm + 30;
454	    return `${String(Math.floor(t / 60)).padStart(2, "0")}:${String(t % 60).padStart(2, "0")}`;
455	  }
456	
457	  const result: Array<{ start: string; end: string; label: string }> = [];
458	  for (let i = 0; i < coachSlots.length; i++) {
459	    const startSlot = coachSlots[i];
460	    if (isCourtBlockedAtLabel(startSlot.label)) continue;
461	    // Walk forward by 30-min steps in label space and confirm each successor
462	    // both exists in the coach's free-slot set AND isn't court-blocked.
463	    let ok = true;
464	    let cursor = startSlot.label;
465	    for (let k = 1; k < slotsNeeded; k++) {
466	      cursor = nextLabel(cursor);
467	      const idx = labelToIdx.get(cursor);
468	      if (idx === undefined) { ok = false; break; }
469	      if (isCourtBlockedAtLabel(cursor)) { ok = false; break; }
470	    }
471	    if (!ok) continue;
472	    // The end timestamp is the start of the slot durationMin minutes later.
473	    const endIdx = i + slotsNeeded - 1;
474	    const lastSlot = coachSlots[endIdx];
475	    result.push({
476	      start: startSlot.start,
477	      end: lastSlot.end,
478	      label: startSlot.label,
479	    });
480	  }
481	
482	  res.json({ slots: result });
483	});
484	
485	export default router;
486

