1	import { eq } from "drizzle-orm";
2	import { db, bookingsTable, userProfilesTable } from "@workspace/db";
3	import { logger } from "./logger";
4	
5	interface BookingForTransfer {
6	  id: number;
7	  coachId: string | null;
8	  coachAmountCents: number | null;
9	  coachTransferId: string | null;
10	  stripePaymentIntentId: string | null;
11	  stripeSessionId: string | null;
12	}
13	
14	/**
15	 * Fire stripe.transfers.create to send the coach their share of a confirmed
16	 * booking. Called from both /payments/confirm and the checkout-completed
17	 * webhook — both paths can race after a successful payment, so this function
18	 * is idempotent at three levels:
19	 *
20	 *  1. Short-circuits if booking.coachTransferId is already set.
21	 *  2. Uses a deterministic Stripe idempotency_key tied to the booking id.
22	 *  3. The CAS update on bookings.coachTransferId only succeeds the first time.
23	 *
24	 * If the booking has no coach attached, this is a no-op.
25	 */
26	export async function maybeIssueCoachTransfer(
27	  booking: BookingForTransfer,
28	  stripe: any,
29	): Promise<void> {
30	  if (!booking.coachId || !booking.coachAmountCents || booking.coachAmountCents <= 0) return;
31	  if (booking.coachTransferId) return;
32	
33	  const [coachProfile] = await db
34	    .select({
