import { eq, and, desc, inArray, or, isNull, isNotNull, ne, sql } from "drizzle-orm";
import { db, coachesTable, coachSportsTable, courtCoachesTable, courtCoachInvitationsTable, courtsTable, facilitiesTable, userProfilesTable, coachPhotosTable, bookingsTable } from "@workspace/db";
import { clerkClient } from "@clerk/express";

