// GET /coaches/me/students ─────────────────────────────────────────────────
// Returns a deduplicated client roster for the authenticated coach. Registered
// students are grouped by bookerUserId (Clerk PII enriched server-side); guests
// are grouped by customerEmail. Both include lesson-count and last-lesson-date
// aggregates. Sorted newest-first by lastLessonDate.
router.get("/coaches/me/students", requireCoach, async (req, res): Promise<void> => {
  const coachUserId = (await resolveCoachUserId(req))!;

  const [registeredRaw, guestRaw] = await Promise.all([
    // Group registered bookers by Clerk user ID
    db
      .select({
        bookerUserId: bookingsTable.bookerUserId,
        totalLessons: sql<number>`cast(count(*) as int)`,
        lastLessonDate: sql<string>`max(${bookingsTable.date})`,
      })
      .from(bookingsTable)
      .where(and(
        eq(bookingsTable.coachId, coachUserId),
        ne(bookingsTable.status, "cancelled"),
        isNotNull(bookingsTable.bookerUserId),
      ))
      .groupBy(bookingsTable.bookerUserId),

    // Group guests by email (bookerUserId is null)
    db
      .select({
        customerEmail: bookingsTable.customerEmail,
        customerName: sql<string>`max(${bookingsTable.customerName})`,
        totalLessons: sql<number>`cast(count(*) as int)`,
        lastLessonDate: sql<string>`max(${bookingsTable.date})`,
      })
      .from(bookingsTable)
      .where(and(
        eq(bookingsTable.coachId, coachUserId),
        ne(bookingsTable.status, "cancelled"),
        isNull(bookingsTable.bookerUserId),
      ))
      .groupBy(bookingsTable.customerEmail),
  ]);

  // Batch-fetch Clerk PII for registered students (max 100 per call)
  const clerkUserMap: Record<string, { name: string; email: string; imageUrl: string | null }> = {};
  const registeredIds = registeredRaw
    .map(r => r.bookerUserId)
    .filter((id): id is string => id != null);

  if (registeredIds.length > 0) {
    const CHUNK = 100;
    for (let i = 0; i < registeredIds.length; i += CHUNK) {
      const chunk = registeredIds.slice(i, i + CHUNK);
      try {
        const { data: users } = await clerkClient.users.getUserList({ userId: chunk, limit: CHUNK });
        for (const u of users) {
          clerkUserMap[u.id] = {
            name: [u.firstName, u.lastName].filter(Boolean).join(" ").trim() || u.username || "Mokinys",
            email: u.primaryEmailAddress?.emailAddress ?? "",
            imageUrl: u.imageUrl ?? null,
          };
        }
      } catch {
        // Proceed with whatever was fetched — Clerk unavailability shouldn't
        // break the entire roster.
      }
    }
  }

  type StudentRow = {
    key: string;
    bookerUserId: string | null;
    isGuest: boolean;
    name: string | null;
    email: string | null;
    imageUrl: string | null;
    totalLessons: number;
    lastLessonDate: string;
  };

  const students: StudentRow[] = [
    ...registeredRaw.map((r): StudentRow => {
      const clerk = r.bookerUserId ? clerkUserMap[r.bookerUserId] : null;
      return {
        key: `user:${r.bookerUserId}`,
        bookerUserId: r.bookerUserId,
        isGuest: false,
        name: clerk?.name ?? null,
        email: clerk?.email ?? null,
        imageUrl: clerk?.imageUrl ?? null,
        totalLessons: r.totalLessons,
        lastLessonDate: r.lastLessonDate,
      };
    }),
    ...guestRaw.map((r): StudentRow => ({
      key: `guest:${r.customerEmail}`,
      bookerUserId: null,
      isGuest: true,
      name: r.customerName ?? null,
      email: r.customerEmail,
      imageUrl: null,
      totalLessons: r.totalLessons,
      lastLessonDate: r.lastLessonDate,
    })),
  ].sort((a, b) => b.lastLessonDate.localeCompare(a.lastLessonDate));

  res.json(students);
});

export default router;

