129	function isoToLocalHM(iso: string): { date: string; hm: string } {
130	  const d = new Date(iso);
131	  return { date: ymd(d), hm: `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}` };
132	}
133	
134	// Build a (date → HH:MM → Cell) map from raw schedule data so the renderer can
135	// just look up `cells[date][slot]` per row.
136	function buildCellMap(
137	  days: string[],
138	  workingHours: WorkingHour[],
139	  blocks: BlockedSlot[],
140	  bookings: ScheduleBooking[],
141	): Record<string, Record<string, Cell>> {
142	  const out: Record<string, Record<string, Cell>> = {};
143	  for (const d of days) {
144	    const dayCells: Record<string, Cell> = {};
145	    const slots = slotsForDay(d, workingHours);
146	    for (const s of slots) dayCells[s] = { kind: "free", slot: s };
147	    out[d] = dayCells;
148	  }
149	  // Apply blocks. A block can span multiple slots; mark every 30-min slot it
150	  // covers as blocked. We trust the user's working-hours envelope — blocks
151	  // outside it are ignored for display.
152	  for (const b of blocks) {
153	    const startLocal = isoToLocalHM(b.startTime);
154	    const endLocal = isoToLocalHM(b.endTime);
155	    const startMin = toMin(startLocal.hm);
156	    const endMin = endLocal.date === startLocal.date ? toMin(endLocal.hm) : 24 * 60;
157	    if (!out[startLocal.date]) continue;
158	    for (let m = startMin; m < endMin; m += 30) {
159	      const slot = fromMin(m);
160	      if (out[startLocal.date][slot]) out[startLocal.date][slot] = { kind: "blocked", block: b };
161	    }
162	  }
163	  for (const bk of bookings) {
164	    if (!out[bk.date]) continue;
165	    const startMin = toMin(bk.startTime);
166	    const endMin = toMin(bk.endTime);
167	    for (let m = startMin; m < endMin; m += 30) {
168	      const slot = fromMin(m);
169	      if (out[bk.date][slot]) out[bk.date][slot] = { kind: "booked", booking: bk };
170	    }
171	  }
172	  return out;
173	}
