177	export function CoachScheduleCalendar() {
178	  const { asCoachId } = useViewAsCoach();
179	  const isViewingAs = asCoachId != null;
180	  const [view, setView] = useState<"day" | "week">("day");
181	  const [anchor, setAnchor] = useState<string>(ymd(new Date()));
182	
183	  // For week view, anchor snaps to the Monday of the week.
184	  const weekStart = useMemo(() => {
185	    const d = new Date(anchor + "T00:00:00");
186	    // JS getDay: 0=Sun..6=Sat. We want Mon..Sun ordering, so shift to Monday.
187	    const offset = (d.getDay() + 6) % 7;
188	    d.setDate(d.getDate() - offset);
189	    return ymd(d);
190	  }, [anchor]);
191	
192	  const from = view === "day" ? anchor : weekStart;
193	  const to = view === "day" ? anchor : addDays(weekStart, 6);
194	
195	  const { data, isLoading } = useQuery<ScheduleResponse>({
196	    queryKey: ["coach-schedule", from, to, asCoachId],
197	    queryFn: () => customFetch<ScheduleResponse>(
198	      withCoachViewAs(`${API}/coaches/me/schedule?from=${from}&to=${to}`),
199	    ),
200	  });
201	
202	  // `range` is omitted when the user has no coach record yet (server short-
203	  // circuits with empty arrays). Fall back to the locally-computed range so
204	  // the empty-state UI still renders.
205	  const days = data?.range?.days ?? (view === "day" ? [anchor] : Array.from({ length: 7 }, (_, i) => addDays(weekStart, i)));
206	  const cells = useMemo(() => {
207	    if (!data) return {};
208	    return buildCellMap(days, data.workingHours, data.blocks, data.bookings);
209	  }, [data, days]);
210	
211	  // The union of all slot times shown across visible days. Used as the row
212	  // axis for the week grid so every column lines up. Day view uses only the
213	  // single day's slots.
214	  const allSlots = useMemo(() => {
215	    const s = new Set<string>();
216	    for (const d of days) for (const slot of Object.keys(cells[d] ?? {})) s.add(slot);
217	    return Array.from(s).sort();
218	  }, [cells, days]);
219	
220	  // ─── Modal state ──────────────────────────────────────────────────────────
221	  const [openAction, setOpenAction] = useState<{ date: string; slot: string } | null>(null);
222	  const [openBooking, setOpenBooking] = useState<ScheduleBooking | null>(null);
223	  const [openRemoveBlock, setOpenRemoveBlock] = useState<BlockedSlot | null>(null);
224	
225	  const onCellClick = (date: string, slot: string) => {
226	    const c = cells[date]?.[slot];
227	    if (!c) return;
228	    if (c.kind === "free") setOpenAction({ date, slot });
229	    else if (c.kind === "booked") setOpenBooking(c.booking);
230	    else if (c.kind === "blocked") setOpenRemoveBlock(c.block);
231	  };
232	
233	  return (
234	    <section className="space-y-3">
235	      <header className="flex flex-wrap items-center gap-3">
236	        <div className="flex-1 min-w-0">
237	          <h2 className="text-lg font-semibold tracking-tight flex items-center gap-2">
238	            <CalendarDays className="h-4 w-4" />
239	            Tvarkaraštis
240	          </h2>
241	          <p className="text-xs text-muted-foreground">
242	            Spauskite ant langelio: laisvą — užblokuoti arba rezervuoti, užimtą — peržiūrėti.
243	          </p>
244	        </div>
245	        <Tabs value={view} onValueChange={(v) => setView(v as "day" | "week")}>
246	          <TabsList className="h-8">
247	            <TabsTrigger value="day" className="text-xs px-3">Diena</TabsTrigger>
248	            <TabsTrigger value="week" className="text-xs px-3">Savaitė</TabsTrigger>
249	          </TabsList>
250	        </Tabs>
251	      </header>
252	
253	      <DateNav
254	        view={view}
255	        anchor={anchor}
256	        weekStart={weekStart}
257	        onPrev={() => setAnchor((a) => addDays(a, view === "day" ? -1 : -7))}
258	        onNext={() => setAnchor((a) => addDays(a, view === "day" ? 1 : 7))}
259	        onToday={() => setAnchor(ymd(new Date()))}
260	      />
261	
262	      {isLoading ? (
263	        <Skeleton className="h-64 rounded-2xl" />
264	      ) : view === "day" ? (
265	        <DayGrid date={anchor} cells={cells[anchor] ?? {}} onSlotClick={(slot) => onCellClick(anchor, slot)} />
266	      ) : (
267	        <WeekGrid days={days} slots={allSlots} cells={cells} onCellClick={onCellClick} />
268	      )}
269	
270	      {/* Slot action: block or reserve manually */}
271	      {openAction && (
272	        <SlotActionDialog
273	          date={openAction.date}
274	          slot={openAction.slot}
275	          isViewingAs={isViewingAs}
276	          onClose={() => setOpenAction(null)}
277	        />
278	      )}
279	
280	      {/* Booking details + cancel */}
281	      {openBooking && (
282	        <BookingDetailsDialog
283	          booking={openBooking}
284	          isViewingAs={isViewingAs}
285	          onClose={() => setOpenBooking(null)}
286	        />
287	      )}
288	
289	      {/* Remove block */}
290	      {openRemoveBlock && (
291	        <RemoveBlockDialog
292	          block={openRemoveBlock}
293	          isViewingAs={isViewingAs}
294	          onClose={() => setOpenRemoveBlock(null)}
295	        />
296	      )}
297	    </section>
298	  );
299	}
