          <TabsTrigger value="week" className="text-xs px-3">Savaitė</TabsTrigger>
        </TabsList>
      </Tabs>
    </header>

    {/* Active student filter chip — shown when navigated from the CRM page */}
    {studentFilter && (
      <div className="flex items-center gap-2 flex-wrap">
        <span className="text-xs text-muted-foreground">Filtruojama pagal mokinį:</span>
        <span className="inline-flex items-center gap-1.5 bg-primary/10 text-primary text-xs font-medium px-2.5 py-1 rounded-full">
          <User className="h-3 w-3" />
          {studentFilter}
          <button
            type="button"
            onClick={() => setStudentFilter(undefined)}
            className="ml-0.5 hover:text-primary/70 transition-colors"
            aria-label="Pašalinti filtrą"
          >
            <X className="h-3 w-3" />
          </button>
        </span>
      </div>
    )}

    <DateNav
      view={view}
      anchor={anchor}
      weekStart={weekStart}
      onPrev={() => setAnchor((a) => addDays(a, view === "day" ? -1 : -7))}
      onNext={() => setAnchor((a) => addDays(a, view === "day" ? 1 : 7))}
      onToday={() => setAnchor(ymd(new Date()))}
    />

    {isLoading ? (
      <Skeleton className="h-64 rounded-2xl" />
    ) : view === "day" ? (
      <DayGrid date={anchor} cells={cells[anchor] ?? {}} matchesFilter={matchesFilter} onSlotClick={(slot) => onCellClick(anchor, slot)} />
    ) : (
      <WeekGrid days={days} slots={allSlots} cells={cells} matchesFilter={matchesFilter} onCellClick={onCellClick} />
    )}

