41	  const d = new Date(iso);
42	  const diff = Date.now() - d.getTime();
43	  const min = Math.floor(diff / 60000);
44	  if (min < 1) return "dabar";
45	  if (min < 60) return `${min}min`;
46	  const h = Math.floor(min / 60);
47	  if (h < 24) return `${h}h`;
48	  return d.toLocaleDateString("lt-LT", { month: "short", day: "numeric" });
49	}
